use std::collections::BinaryHeap;use std::cmp::Reverse;impl Solution{pub fn k_smallest_pairs(a:Vec<i32>,b:Vec<i32>,k:i32)->Vec<Vec<i32>>{let mut o=vec![];if a.is_empty()||b.is_empty(){return o}let mut h=BinaryHeap::new();for i in 0..a.len().min(k as usize){h.push(Reverse((a[i]as i64+b[0]as i64,i,0usize)));}for _ in 0..k{let Some(Reverse((_,i,j)))=h.pop()else{break};o.push(vec![a[i],b[j]]);if j+1<b.len(){h.push(Reverse((a[i]as i64+b[j+1]as i64,i,j+1)));}}o}}
